const statusNames={watching:'\u041E\u0436\u0438\u0434\u0430\u043D\u0438\u0435',voting:'\u0413\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u043D\u0438\u0435',finished:'\u0417\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u043E',stopped:'\u041E\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E',expired:'\u041B\u0438\u043C\u0438\u0442 \u0432\u0440\u0435\u043C\u0435\u043D\u0438',interrupted:'\u041F\u0440\u0435\u0440\u0432\u0430\u043D\u043E',error:'\u041E\u0448\u0438\u0431\u043A\u0430',skipped:'\u041F\u0440\u043E\u043F\u0443\u0449\u0435\u043D\u043E',queued:'\u0412 \u043E\u0447\u0435\u0440\u0435\u0434\u0438',preparing:'\u041F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043A\u0430',sending:'\u041E\u0442\u043F\u0440\u0430\u0432\u043A\u0430',confirmed:'\u041F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u043E',uncertain:'\u041D\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u043E',failed:'\u041D\u0435 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u043E'};
