  $('job-progress').replaceChildren();if(j?.rows?.length)$('job-progress').append(node('div',j.rows.filter(r=>r.status==='confirmed').length+' \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u043E \xB7 '+j.rows.filter(r=>r.status==='uncertain').length+' \u0431\u0435\u0437 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u044F \xB7 '+j.rows.length+' \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432','progress-text'));
  $('results').replaceChildren();$('result-table').hidden=!j?.rows?.length;
  for(const r of j?.rows||[]){const tr=node('tr'),result=node('td',statusNames[r.status]||r.status,'result-'+r.status);result.append(node('small',r.message));tr.append(node('td',r.login),node('td',(r.choice+1)+'. '+r.answer),result);$('results').append(tr);}
  $('history').replaceChildren();for(const h of j?.history||[])$('history').append(node('div',h.title+' \xB7 '+h.confirmed+' / '+h.total+' \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u043E','history-item'));
  if(running){const left=Math.max(0,Math.ceil((j.deadline-Date.now())/60000));$('job-status').textContent+=' \xB7 \u0434\u043E '+left+' \u043C\u0438\u043D';}
