async function openAccount(login,mode){
  dialogLogin=login;dialogMode=mode;$('dialog-title').textContent=(mode==='inspect'?'\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u043A\u0430\u043D\u0430\u043B\u0430 \xB7 ':'\u0412\u0445\u043E\u0434 \xB7 ')+login;$('dialog-error').textContent='';
  const data=await api(mode==='inspect'?'account/inspect':'account/login',{login,channel:$('channel').value.trim()});
  const url=new URL(data.url);if(url.protocol!=='https:'||url.hostname!=='live.browser.run')throw new Error('\u041D\u0435\u043A\u043E\u0440\u0440\u0435\u043A\u0442\u043D\u0430\u044F \u0441\u0441\u044B\u043B\u043A\u0430 Cloudflare.');
  $('live-link').href=url.href;$('save-login').hidden=mode==='inspect';$('login-dialog').showModal();await refresh();
}
async function boot(){try{const s=await api('session');csrf=s.csrf;$('login-screen').hidden=true;$('app').hidden=false;apply(await api('state'));importFragment();}catch(e){showLogin();if(!e.message.includes('\u0412\u043E\u0439\u0434\u0438'))$('login-error').textContent=e.message;}}
function importFragment(){
  if(!location.hash.startsWith('#import='))return;let data;
  try{data=JSON.parse(decodeURIComponent(location.hash.slice(8)));}catch{toast('\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0438\u043C\u043F\u043E\u0440\u0442.');return;}finally{history.replaceState(null,'',location.pathname);}
  if(typeof data.channel==='string')$('channel').value=data.channel;
  if(Array.isArray(data.logins)){$('logins').value=data.logins.filter(l=>typeof l==='string'&&/^[a-z0-9_]{1,25}$/i.test(l)).join(', ');toast('\u041B\u043E\u0433\u0438\u043D\u044B \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u0435\u043D\u044B. \u041D\u0430\u0436\u043C\u0438 \xAB\u0414\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u044B\xBB \u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u0438 \u0432\u0445\u043E\u0434 \u0434\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0433\u043E.');}
}
$('login-form').onsubmit=async e=>{e.preventDefault();$('login-error').textContent='';try{await api('login',{password:$('password').value});$('password').value='';await boot();}catch(e){$('login-error').textContent=e.message;}};
$('logout').onclick=()=>action(async()=>{await api('logout',{});showLogin();});
$('add-form').onsubmit=e=>{e.preventDefault();action(async()=>{const logins=$('logins').value.split(/[\\s,;]+/).filter(Boolean);apply(await api('add',{logins}));$('logins').value='';});};
